}

/* Fold markers - Light Theme */
.cm-foldMarker {
  background: #f6f8fa;
  border: 1px solid #d1d9e0;
  color: #656d76;
  border-radius: 2px;
  padding: 0 4px;
  margin: 0 2px;
  font-size: 12px;
}

/* Error highlighting - Light Theme */
.cm-lintRange-error {
  background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' width='6' height='3'%3e%3cpath d='m0 3 l3 -3 l3 3' stroke='%23da3633' fill='none' stroke-width='.7'/%3e%3c/svg%3e");
  background-repeat: repeat-x;
  background-position: bottom;
}

/* CodeMirror Collaboration Cursors - Light Theme */
.cm-ySelectionInfo {
  position: absolute;
  top: -1.4em;
  left: -1px;
  font-size: 12px;
  font-weight: 600;
  line-height: normal;
  padding: 0.1rem 0.3rem;
  border-radius: 3px 3px 3px 0;
  color: #ffffff;
  white-space: nowrap;
  user-select: none;
  pointer-events: none;
  z-index: 1000;
}

.cm-ySelection {
  background-color: rgba(9, 105, 218, 0.15);
  border-left: 2px solid #0969da;
  border-right: 2px solid #0969da;
  margin-left: -1px;
  margin-right: -1px;
  pointer-events: none;
}

/* Loading Spinner Component */
.loading-spinner-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  animation: fadeIn 0.3s ease-out;
}

.loading-content {
  text-align: center;
  animation: slideUp 0.5s ease-out;
}

.loading-spinner {
  position: relative;
  width: 60px;
  height: 60px;
  margin: 0 auto 24px;
}

.spinner-ring {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 3px solid transparent;
  border-radius: 50%;
  animation: spin 2s linear infinite;
}

.spinner-ring:nth-child(1) {
  border-top-color: #667eea;
  animation-duration: 2s;
  animation-delay: 0s;
}

.spinner-ring:nth-child(2) {
  border-right-color: #764ba2;
  animation-duration: 2.5s;
  animation-delay: 0.2s;
  transform: scale(0.8);
}

.spinner-ring:nth-child(3) {
  border-bottom-color: #fd7e14;
  animation-duration: 3s;
  animation-delay: 0.4s;
  transform: scale(0.6);
}

.loading-text {
  font-size: 16px;
  font-weight: 600;
  color: #495057;
  margin-bottom: 8px;
  font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
  animation: textPulse 2s ease-in-out infinite;
}

.loading-subtitle {
  font-size: 14px;
  color: #6c757d;
  font-weight: 500;
  opacity: 0.8;
  animation: fadeInUp 0.8s ease-out 0.3s both;
}

/* Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes textPulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 0.8;
    transform: translateY(0);
  }
}

/* Loading state transitions */
.codemirror-loading-overlay.fade-out {
  animation: fadeOut 0.3s ease-out forwards;
}

@keyframes fadeOut {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
